<?php
require_once __DIR__ . '/../helpers/auth.php'; requireLogin();
require_once __DIR__ . '/../models/ProductoModel.php';
$productos=(new ProductoModel())->obtenerTodos();
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ventas - Mi Stock</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head>
<body class="bg-light"><div class="container-fluid p-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2>🛒 Registrar venta</h2><a href="dashboard.php" class="btn btn-outline-secondary">Volver</a></div>
<div class="row g-4"><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-header bg-primary text-white">Productos</div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Código</th><th>Producto</th><th>Precio</th><th>Stock</th><th></th></tr></thead><tbody><?php foreach($productos as $p):?><tr><td><?=e($p['Codigo'])?></td><td><?=e($p['Nombre'])?></td><td>$<?=number_format((float)$p['PrecioVenta'],0,',','.')?></td><td><span class="badge <?=$p['StockActual']>0?'bg-success':'bg-danger'?>"><?=$p['StockActual']?></span></td><td><button class="btn btn-sm btn-outline-primary" onclick='add(<?=json_encode((int)$p['IdProducto'])?>,<?=json_encode($p['Nombre'])?>,<?=json_encode((float)$p['PrecioVenta'])?>,<?=json_encode((int)$p['StockActual'])?>)' <?=$p['StockActual']<=0?'disabled':''?>>Agregar</button></td></tr><?php endforeach;?></tbody></table></div></div></div>
<div class="col-lg-5"><div class="card border-0 shadow-sm"><div class="card-header bg-dark text-white">Detalle de venta</div><div class="card-body"><div class="row g-2 mb-3"><div class="col-6"><label class="form-label">Documento</label><select id="tipo" class="form-select"><option>BOLETA</option><option>FACTURA</option><option>OTRO</option></select></div><div class="col-6"><label class="form-label">N° documento</label><input id="numero" class="form-control"></div></div><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Producto</th><th>Cant.</th><th>Subtotal</th><th></th></tr></thead><tbody id="carrito"></tbody></table></div><div class="d-flex justify-content-between fs-5 fw-bold"><span>Total</span><span id="total">$0</span></div><button class="btn btn-success w-100 mt-3" onclick="vender()">Confirmar venta</button></div></div></div></div></div>
<script>
let cart=[]; const money=n=>n.toLocaleString('es-CL',{maximumFractionDigits:0});
function add(id,nombre,precio,stock){let x=cart.find(i=>i.id_producto===id);if(x){if(x.cantidad>=stock)return alert('No hay más stock disponible.');x.cantidad++;}else cart.push({id_producto:id,nombre,precio_unitario:precio,cantidad:1});render();}
function del(id){cart=cart.filter(x=>x.id_producto!==id);render();}
function render(){let b=document.getElementById('carrito');b.innerHTML='';let total=0;cart.forEach(x=>{let s=x.cantidad*x.precio_unitario;total+=s;b.innerHTML+=`<tr><td>${x.nombre}</td><td>${x.cantidad}</td><td>$${money(s)}</td><td><button class="btn btn-sm btn-outline-danger" onclick="del(${x.id_producto})">×</button></td></tr>`});document.getElementById('total').innerText='$'+money(total);}
async function vender(){if(!cart.length)return alert('Agrega productos.');let total=cart.reduce((s,x)=>s+x.cantidad*x.precio_unitario,0);const r=await fetch('../controllers/VentaController.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({detalles:cart,total,tipo_documento:document.getElementById('tipo').value,numero_documento:document.getElementById('numero').value})});const d=await r.json();alert(d.message);if(d.success)location.reload();}
</script></body></html>
